import os, sys, csv, json, math, itertools
from pyscipopt import Model, quicksum

BASE = "/app"
DATA = os.path.join(BASE, "data")
SUB = os.path.join(BASE, "submissions")
os.makedirs(SUB, exist_ok=True)

# ---------------- Load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    cfg = json.load(f)

DEPOT = cfg["depot_id"]
TRUCK_SVC_PER_KG = cfg["truck_service_minutes_per_kg"]
DRONE_SETUP = cfg["drone_setup_minutes"]
BOAT_SETUP = cfg["boat_setup_minutes"]
BOAT_UNLOAD = cfg["boat_unload_minutes_per_shelter"]
TRUCK_FIXED = cfg["truck_fixed_stop_minutes"]
DRONE_CAP = cfg["drone_capacity_kg"]
DRONE_ENDUR = cfg["drone_endurance_minutes"]
BOAT_CAP = cfg["boat_capacity_kg"]
BOAT_TRIP_LIMIT = cfg["boat_trip_limit_minutes"]
LATE_PEN = cfg["late_penalty_per_weighted_minute"]
RISK_PEN = cfg["risk_penalty_minutes_per_point"]

staging = {}
with open(os.path.join(DATA, "staging_points.csv")) as f:
    for r in csv.DictReader(f):
        staging[r["node_id"]] = {
            "name": r["node_name"],
            "clearance": r["launch_clearance"].strip(),
            "ramp": int(r["boat_ramp"]),
            "handling": float(r["handling_minutes"]),
        }

roads = []
with open(os.path.join(DATA, "road_edges.csv")) as f:
    for r in csv.DictReader(f):
        if int(r["usable_after_flood"]) == 1:
            roads.append((r["from_node"], r["to_node"], float(r["travel_minutes"])))

shelters = {}
with open(os.path.join(DATA, "shelters.csv")) as f:
    for r in csv.DictReader(f):
        shelters[r["shelter_id"]] = {
            "name": r["shelter_name"],
            "area": r["area_type"].strip(),
            "dry_node": r["nearest_dry_node"].strip() or None,
            "demand": float(r["demand_kg"]),
            "priority": r["priority"].strip(),
            "deadline": float(r["deadline_minutes"]),
        }

drone_opts = []
with open(os.path.join(DATA, "drone_options.csv")) as f:
    for r in csv.DictReader(f):
        drone_opts.append({
            "shelter": r["shelter_id"],
            "launch": r["launch_node"],
            "flight": float(r["flight_minutes"]),
            "risk": float(r["landing_risk"]),
            "payload": int(r["payload_feasible"]),
        })

boat_travel = {}
with open(os.path.join(DATA, "boat_travel.csv")) as f:
    for r in csv.DictReader(f):
        boat_travel[(r["from_id"], r["to_id"])] = float(r["minutes"])

weights = {}
with open(os.path.join(DATA, "priority_weights.csv")) as f:
    for r in csv.DictReader(f):
        weights[r["priority"].strip()] = float(r["weight"])

# ---------------- Preprocessing ----------------
nodes = [DEPOT] + sorted(staging.keys())
nN = len(nodes)
idx = {n: i for i, n in enumerate(nodes)}

# shortest paths
INF = float("inf")
dist = [[INF]*nN for _ in range(nN)]
for i in range(nN):
    dist[i][i] = 0.0
for (a, b, t) in roads:
    ia, ib = idx[a], idx[b]
    if t < dist[ia][ib]:
        dist[ia][ib] = t
        dist[ib][ia] = t
for k in range(nN):
    for i in range(nN):
        dik = dist[i][k]
        if dik == INF:
            continue
        for j in range(nN):
            nd = dik + dist[k][j]
            if nd < dist[i][j]:
                dist[i][j] = nd

dry_shelters = [s for s in shelters if shelters[s]["area"] == "dry"]
flooded_shelters = [s for s in shelters if shelters[s]["area"] == "flooded"]

# feasible drone options
MAX_WEATHER = 1.22
feas_drone = []
for o in drone_opts:
    s, l = o["shelter"], o["launch"]
    if s not in shelters or shelters[s]["area"] != "flooded":
        continue
    if l not in staging:
        continue
    if o["payload"] != 1:
        continue
    if shelters[s]["demand"] > DRONE_CAP:
        continue
    if staging[l]["clearance"] == "poor":
        continue
    if 2.0 * o["flight"] * MAX_WEATHER > DRONE_ENDUR:
        continue
    feas_drone.append(o)
drone_by_shelter = {}
for o in feas_drone:
    drone_by_shelter.setdefault(o["shelter"], []).append(o)

ramps = [s for s in staging if staging[s]["ramp"] == 1]

# boat candidate legs: ramp->shelter and shelter->shelter
boat_ramp_to = {}
boat_sh_to = {}
for (a, b), t in boat_travel.items():
    if a in ramps and b in shelters and shelters[b]["area"] == "flooded":
        boat_ramp_to.setdefault(a, {})[b] = t
    elif a in shelters and shelters[a]["area"] == "flooded" and b in shelters and shelters[b]["area"] == "flooded":
        boat_sh_to.setdefault(a, {})[b] = t

# Max boat trip positions: capacity bound
K = 0
while K < 12:
    K += 1
    # min demand among flooded
    min_d = min(shelters[s]["demand"] for s in flooded_shelters)
    if (K+1) * min_d > BOAT_CAP:
        break
K = min(K, 6)

# ---------------- Model ----------------
model = Model("flood_relief")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env is not None:
    try:
        time_limit = min(time_limit, float(env))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

# truck arc vars (exclude self loops)
x = {}
for a in nodes:
    for b in nodes:
        if a == b:
            continue
        ia, ib = idx[a], idx[b]
        if dist[ia][ib] == INF:
            continue
        x[(a, b)] = model.addVar(name=f"x_{a}_{b}", vtype="B", lb=0, ub=1, obj=0.0)

# MTZ position vars
u = {}
for a in nodes:
    u[a] = model.addVar(name=f"u_{a}", vtype="C", lb=0, ub=nN-1, obj=0.0)
model.addCons(u[DEPOT] == 0, name="u_depot")

# node visit vars
visit = {}
for s in nodes:
    if s == DEPOT:
        continue
    visit[s] = model.addVar(name=f"v_{s}", vtype="B", lb=0, ub=1, obj=0.0)

# flow conservation
for a in nodes:
    model.addCons(
        quicksum(x[(a, b)] for b in nodes if (a, b) in x) ==
        quicksum(x[(b, a)] for b in nodes if (b, a) in x),
        name=f"flow_{a}")
# depot out = 1
model.addCons(quicksum(x[(DEPOT, b)] for b in nodes if (DEPOT, b) in x) == 1, name="depot_out")
model.addCons(quicksum(x[(b, DEPOT)] for b in nodes if (b, DEPOT) in x) == 1, name="depot_in")

# visit linking
for s in nodes:
    if s == DEPOT:
        continue
    model.addCons(
        quicksum(x[(a, s)] for a in nodes if (a, s) in x) == visit[s],
        name=f"visit_{s}")

# MTZ big-M
M = nN
for (a, b) in x:
    model.addCons(u[b] >= u[a] + 1 - M * (1 - x[(a, b)]), name=f"mtz_{a}_{b}")

# ---------------- Service variables ----------------
y = {}  # dry truck service
for s in dry_shelters:
    dn = shelters[s]["dry_node"]
    y[s] = model.addVar(name=f"y_{s}", vtype="B", lb=0, ub=1, obj=0.0)
    model.addCons(y[s] <= visit[dn], name=f"ylink_{s}")
    model.addCons(y[s] == 1, name=f"ydemand_{s}")

z = {}  # drone option use
for o in feas_drone:
    key = (o["shelter"], o["launch"])
    z[key] = model.addVar(name=f"z_{o['shelter']}_{o['launch']}", vtype="B", lb=0, ub=1, obj=0.0)
    model.addCons(z[key] <= visit[o["launch"]], name=f"zlink_{o['shelter']}_{o['launch']}")

# boat: q[i, s, l] shelter i at position l of trip from ramp s
q = {}
for s in ramps:
    for i in flooded_shelters:
        if i not in boat_ramp_to.get(s, {}):
            continue
        for l in range(1, K+1):
            q[(i, s, l)] = model.addVar(name=f"q_{i}_{s}_{l}", vtype="B", lb=0, ub=1, obj=0.0)
            model.addCons(q[(i, s, l)] <= visit[s], name=f"qvisit_{i}_{s}_{l}")

# w[i, j, s, l]: j follows i at position l+1 in trip from s
w = {}
for s in ramps:
    for i in flooded_shelters:
        for j in flooded_shelters:
            if i == j:
                continue
            if j not in boat_sh_to.get(i, {}):
                continue
            for l in range(1, K):
                w[(i, j, s, l)] = model.addVar(name=f"w_{i}_{j}_{s}_{l}", vtype="B", lb=0, ub=1, obj=0.0)

# Each flooded shelter served exactly once (drone or boat)
for i in flooded_shelters:
    terms = [z[(i, l)] for (i2, l) in z if i2 == i]
    terms += [q[(i, s, l)] for (i2, s, l) in q if i2 == i]
    model.addCons(quicksum(terms) == 1, name=f"serve_{i}")

# Boat trip structure per ramp:
for s in ramps:
    # at most one trip starts at position 1 (i.e., sum over i of q[i,s,1] <= 1)
    model.addCons(quicksum(q[(i, s, 1)] for i in flooded_shelters if (i, s, 1) in q) <= 1, name=f"tripstart_{s}")
    # position flow: q[i,s,l+1] = sum_j w[j,i,s,l]
    for i in flooded_shelters:
        if (i, s, 1) not in q:
            continue
        for l in range(1, K):
            lhs = quicksum(w[(j, i, s, l)] for j in flooded_shelters if (j, i, s, l) in w)
            if (i, s, l+1) in q:
                model.addCons(q[(i, s, l+1)] == lhs, name=f"qflow_{i}_{s}_{l}")
            else:
                model.addCons(lhs == 0, name=f"qflow0_{i}_{s}_{l}")
    # w implies both positions
    for (i, j, s2, l) in w:
        if s2 != s:
            continue
        model.addCons(w[(i, j, s, l)] <= q[(i, s, l)], name=f"wimp1_{i}_{j}_{s}_{l}")
        model.addCons(w[(i, j, s, l)] <= q[(j, s, l+1)], name=f"wimp2_{i}_{j}_{s}_{l}")
    # capacity per position-prefix: total demand of shelters in trip <= BOAT_CAP
    # trip demand = sum_l sum_i demand_i * q[i,s,l] <= BOAT_CAP
    model.addCons(
        quicksum(shelters[i]["demand"] * q[(i, s, l)] for (i, s2, l) in q if s2 == s) <= BOAT_CAP,
        name=f"cap_{s}")
    # trip time: setup + first leg + (travel + unload) per subsequent position <= limit
    # time = BOAT_SETUP + sum_i (travel s->i)*q[i,s,1] + sum_{i,j,l} (travel i->j + UNLOAD)*w[i,j,s,l] + UNLOAD * (shelters at pos1)
    time_terms = []
    for i in flooded_shelters:
        if (i, s, 1) in q:
            time_terms.append(boat_ramp_to[s][i] * q[(i, s, 1)])
            time_terms.append(BOAT_UNLOAD * q[(i, s, 1)])
    for (i, j, s2, l) in w:
        if s2 != s:
            continue
        time_terms.append((boat_sh_to[i][j] + BOAT_UNLOAD) * w[(i, j, s, l)])
    model.addCons(
        BOAT_SETUP + quicksum(time_terms) <= BOAT_TRIP_LIMIT + BOAT_TRIP_LIMIT * (1 - quicksum(q[(i, s, 1)] for i in flooded_shelters if (i, s, 1) in q)),
        name=f"triptime_{s}")

# ---------------- Timing ----------------
# Big time bound
TMAX = 10000.0
tpos = {}
for a in nodes:
    tpos[a] = model.addVar(name=f"T_{a}", vtype="C", lb=0, ub=TMAX, obj=0.0)
model.addCons(tpos[DEPOT] == 0, name="T_depot")

# dwell components
# truck service time at node s (dry shelters)
truck_svc = {}
for s in nodes:
    if s == DEPOT:
        continue
    ts = 0.0
    for i in dry_shelters:
        if shelters[i]["dry_node"] == s:
            ts += TRUCK_FIXED + TRUCK_SVC_PER_KG * shelters[i]["demand"]
    truck_svc[s] = ts

# drone time at node s
def drone_time_at(s):
    terms = []
    for (i, l), var in z.items():
        if l == s:
            o = [oo for oo in feas_drone if oo["shelter"] == i and oo["launch"] == s][0]
            terms.append((DRONE_SETUP + o["flight"] + RISK_PEN * o["risk"]) * var)
    return terms

# boat trip time at ramp s
def boat_time_at(s):
    terms = []
    for i in flooded_shelters:
        if (i, s, 1) in q:
            terms.append(boat_ramp_to[s][i] * q[(i, s, 1)])
            terms.append(BOAT_UNLOAD * q[(i, s, 1)])
    for (i, j, s2, l) in w:
        if s2 == s:
            terms.append((boat_sh_to[i][j] + BOAT_UNLOAD) * w[(i, j, s, l)])
    return terms

# dwell(s) = handling + truck_svc + drone + boat
for s in nodes:
    if s == DEPOT:
        continue
    dwell_terms = [staging[s]["handling"] * visit[s]]
    if truck_svc[s] > 0:
        dwell_terms.append(truck_svc[s] * visit[s])
    for t in drone_time_at(s):
        dwell_terms.append(t)
    for t in boat_time_at(s):
        dwell_terms.append(t)
    model.addCons(
        quicksum(x[(a, s)] for a in nodes if (a, s) in x) * 0 + 0 <= 0 or True, name="dummy")
    # store dwell expression
    dwell_expr[s] = quicksum(dwell_terms) if dwell_terms else 0.0

dwell_expr = {}
for s in nodes:
    if s == DEPOT:
        dwell_expr[s] = 0.0
        continue
    dwell_terms = [staging[s]["handling"] * visit[s]]
    if truck_svc[s] > 0:
        dwell_terms.append(truck_svc[s] * visit[s])
    for t in drone_time_at(s):
        dwell_terms.append(t)
    for t in boat_time_at(s):
        dwell_terms.append(t)
    dwell_expr[s] = quicksum(dwell_terms) if dwell_terms else 0.0

# MTZ time: T[b] >= T[a] + dist + dwell[a]
for (a, b) in x:
    ia, ib = idx[a], idx[b]
    model.addCons(
        tpos[b] >= tpos[a] + dist[ia][ib] + dwell_expr[a] - TMAX * (1 - x[(a, b)]),
        name=f"tmtz_{a}_{b}")

# completion time = T at return to depot: use arc into depot
comp = model.addVar(name="completion", vtype="C", lb=0, ub=TMAX, obj=1.0)
model.addCons(
    comp >= quicksum(tpos[a] + dist[idx[a]][idx[DEPOT]] + dwell_expr[a] * x[(a, DEPOT)] for a in nodes if (a, DEPOT) in x),
    name="comp_def")

# ---------------- Shelter completion times & lateness ----------------
C = {}
L = {}
for s in shelters:
    C[s] = model.addVar(name=f"C_{s}", vtype="C", lb=0, ub=TMAX, obj=0.0)
    L[s] = model.addVar(name=f"L_{s}", vtype="C", lb=0, ub=TMAX, obj=0.0)

# dry: C = T[dry_node] + handling + fixed + svc (served during dwell)
for s in dry_shelters:
    dn = shelters[s]["dry_node"]
    svc = TRUCK_FIXED + TRUCK_SVC_PER_KG * shelters[s]["demand"]
    model.addCons(C[s] >= tpos[dn] + staging[dn]["handling"] + svc - TMAX * (1 - y[s]), name=f"Cdry_{s}")
    model.addCons(C[s] <= tpos[dn] + staging[dn]["handling"] + svc + TMAX * (1 - y[s]), name=f"Cdryub_{s}")

# drone: C = T[launch] + handling + setup + flight
for (i, l), var in z.items():
    o = [oo for oo in feas_drone if oo["shelter"] == i and oo["launch"] == l][0]
    model.addCons(C[i] >= tpos[l] + staging[l]["handling"] + DRONE_SETUP + o["flight"] - TMAX * (1 - var), name=f"Cdr_{i}_{l}")
    model.addCons(C[i] <= tpos[l] + staging[l]["handling"] + DRONE_SETUP + o["flight"] + TMAX * (1 - var), name=f"Cdrub_{i}_{l}")

# boat: C = T[ramp] + handling + setup + cumulative offset at position
# offset for position l: computed via position-offset vars
# off[i, s, l] = cumulative time from ramp departure to completion of shelter i at position l
off = {}
for s in ramps:
    for i in flooded_shelters:
        if (i, s, 1) in q:
            off[(i, s, 1)] = model.addVar(name=f"off_{i}_{s}_1", vtype="C", lb=0, ub=BOAT_TRIP_LIMIT, obj=0.0)
            model.addCons(off[(i, s, 1)] >= boat_ramp_to[s][i] + BOAT_UNLOAD - BOAT_TRIP_LIMIT * (1 - q[(i, s, 1)]), name=f"offlb1_{i}_{s}")
            model.addCons(off[(i, s, 1)] <= boat_ramp_to[s][i] + BOAT_UNLOAD + BOAT_TRIP_LIMIT * (1 - q[(i, s, 1)]), name=f"offub1_{i}_{s}")
for s in ramps:
    for (i, j, s2, l) in w:
        if s2 != s:
            continue
        # off[j,s,l+1] = off[i,s,l] + travel(i,j) + unload
        model.addCons(off[(j, s, l+1)] >= off[(i, s, l)] + boat_sh_to[i][j] + BOAT_UNLOAD - BOAT_TRIP_LIMIT * (1 - w[(i, j, s, l)]), name=f"offlb_{i}_{j}_{s}_{l}")
        model.addCons(off[(j, s, l+1)] <= off[(i, s, l)] + boat_sh_to[i][j] + BOAT_UNLOAD + BOAT_TRIP_LIMIT * (1 - w[(i, j, s, l)]), name=f"offub_{i}_{j}_{s}_{l}")

for s in flooded_shelters:
    for (i, s2, l) in q:
        if i == s:
            model.addCons(C[s] >= tpos[s2] + staging[s2]["handling"] + BOAT_SETUP + off[(s, s2, l)] - TMAX * (1 - q[(s, s2, l)]), name=f"Cbo_lb_{s}_{s2}_{l}")
            model.addCons(C[s] <= tpos[s2] + staging[s2]["handling"] + BOAT_SETUP + off[(s, s2, l)] + TMAX * (1 - q[(s, s2, l)]), name=f"Cbo_ub_{s}_{s2}_{l}")

# lateness
for s in shelters:
    wt = weights[shelters[s]["priority"]]
    model.addCons(L[s] >= C[s] - shelters[s]["deadline"], name=f"lat_{s}")
    model.addCons(L[s] >= 0, name=f"lat0_{s}")
    comp.chgObj if False else None
    # add penalty to objective
    model.chgVarObj(L[s], LATE_PEN * wt)

# ---------------- Solve ----------------
model.setMinimize()
print("Solving...")
model.optimize()
status = model.getStatus()
print("Status:", status)
print("NSols:", model.getNSols())

sol_path = os.path.join(SUB, "solution.csv")
header = ["row_type", "sequence", "node_id", "trip_id", "mode", "shelter_id", "launch_node"]

def write_solution(rows):
    with open(sol_path, "w", newline="") as f:
        wtr = csv.writer(f)
        wtr.writerow(header)
        for r in rows:
            wtr.writerow(r)

rows = []
if model.getNSols() > 0:
    sol = model.getBestSol()
    print("Objective:", model.getObjVal())

    # truck route: follow arcs from depot
    route = [DEPOT]
    cur = DEPOT
    for _ in range(nN):
        nxt = None
        for b in nodes:
            if (cur, b) in x and model.getVal(x[(cur, b)]) > 0.5:
                nxt = b
                break
        if nxt is None or nxt == DEPOT:
            break
        route.append(nxt)
        cur = nxt
    if route[-1] != DEPOT:
        route.append(DEPOT)

    for seq, node in enumerate(route):
        rows.append(["truck_stop", seq, node, "", "", "", ""])

    # truck deliveries
    for s in dry_shelters:
        if model.getVal(y[s]) > 0.5:
            dn = shelters[s]["dry_node"]
            rows.append(["delivery", "", dn, "", "truck", s, ""])

    # drone deliveries
    trip_counter = 1
    for (i, l), var in z.items():
        if model.getVal(var) > 0.5:
            rows.append(["delivery", "", "", f"DR{trip_counter}", "drone", i, l])
            trip_counter += 1

    # boat trips: reconstruct per ramp
    for s in ramps:
        # find position-1 shelter
        first = None
        for i in flooded_shelters:
            if (i, s, 1) in q and model.getVal(q[(i, s, 1)]) > 0.5:
                first = i
                break
        if first is None:
            continue
        trip_id = f"BT{trip_counter}"
        trip_counter += 1
        order = [first]
        cur_i = first
        l = 1
        while l < K:
            nxt_i = None
            for j in flooded_shelters:
                if (cur_i, j, s, l) in w and model.getVal(w[(cur_i, j, s, l)]) > 0.5:
                    nxt_i = j
                    break
            if nxt_i is None:
                break
            order.append(nxt_i)
            cur_i = nxt_i
            l += 1
        for pos, i in enumerate(order, start=1):
            rows.append(["delivery", pos, "", trip_id, "boat", i, s])

write_solution(rows)
print(f"Wrote {sol_path} with {len(rows)} rows")

# ---------------- Validation ----------------
def validate():
    ok = True
    served = {}
    with open(sol_path) as f:
        rdr = csv.DictReader(f)
        truck_rows = []
        for r in rdr:
            if r["row_type"] == "truck_stop":
                truck_rows.append(r)
            elif r["row_type"] == "delivery":
                sid = r["shelter_id"]
                served.setdefault(sid, []).append(r)
    if not truck_rows:
        print("VALIDATION FAIL: no truck route")
        ok = False
    else:
        seqs = [int(r["sequence"]) for r in truck_rows]
        if seqs != list(range(len(seqs))):
            print("VALIDATION FAIL: truck sequence not 0..n-1")
            ok = False
        if truck_rows[0]["node_id"] != DEPOT or truck_rows[-1]["node_id"] != DEPOT:
            print("VALIDATION FAIL: route must start/end at depot")
            ok = False
    for s in shelters:
        if s not in served or len(served[s]) != 1:
            print(f"VALIDATION FAIL: shelter {s} not served exactly once")
            ok = False
    return ok

print("Validation:", "PASS" if validate() else "FAIL")

# log
log_path = os.path.join(SUB, "solve_log.md")
with open(log_path, "a") as f:
    f.write(f"\n## Run result\n- Status: {status}\n- NSols: {model.getNSols()}\n")
    if model.getNSols() > 0:
        f.write(f"- Objective: {model.getObjVal():.8f}\n")
    f.write(f"- Rows written: {len(rows)}\n")
model.free()
